// A genuinely nested install — the copy npm places under `trace-dep` when its `nested-dep`
// range conflicts with the top level's. Its principal is the install chain
// `trace-dep>nested-dep` (#92), so this file exists to prove the CLI round-trip carries a
// chain key end to end: observe records it, gen-policy writes it, enforce matches it.
const fs = require("fs");
const path = require("path");

exports.readOwn = () => fs.readFileSync(path.join(__dirname, "nested.txt"), "utf8");
